"""Pre-tool-use guard shared by Claude Code and Codex.

The agents run without permission prompts (Claude bypassPermissions, Codex
approval "never"), so this is the safety net. It enforces workspace rules, not
security: it blocks the accidents that waste time and disk (stray worktrees and
clones, scratch files in the wrong place, backup copies, destructive commands,
AI attribution) and explains the right way in the denial message, so the agent
corrects itself in one step.

Pure functions; the hook wrapper fails open on any error.
"""
from __future__ import annotations

